window.EXAM_CHAPTER_DATA["pol_econ"]["02_资本主义经济制度与生产"] = {"id":"02_资本主义经济制度与生产","name":"资本主义经济制度与生产","kps":[{"id":"KP01","name":"资本主义经济制度的形成","file":"教材笔记/07_政治经济学/02_资本主义经济制度与生产/知识点/KP01_资本主义经济制度的形成.md","questions":[{"id":"pol_econ_02_资本主义经济制度与生产_KP01_1","num":"1","stem":"资本主义经济制度产生的基础是（　）。","options":{"A":"工业革命","B":"商品经济发展和生产者分化","C":"地理大发现","D":"文艺复兴"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP01_2","num":"2","stem":"资本原始积累的实质是（　）。","options":{"A":"资本家勤劳节俭积累资本","B":"用暴力迫使生产者与生产资料分离","C":"扩大再生产","D":"国际贸易"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP01_3","num":"3","stem":"资本主义生产关系萌芽的两个途径是（　）。","options":{"A":"商人包买商控制小商品生产者和小手工业者分化","B":"工业革命和圈地运动","C":"殖民扩张和奴隶贸易","D":"文艺复兴和宗教改革"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP01_4","num":"4","stem":"产业革命对资本主义制度的意义是（　）。","options":{"A":"它使资本主义生产关系最终确立","B":"它只是技术进步","C":"它与制度无关","D":"它导致封建制度复兴"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP01_5","num":"5","stem":"资本主义制度的基础是（　）。","options":{"A":"生产资料私有制和雇佣劳动","B":"市场交换","C":"机器大生产","D":"民主制度"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP01_6","num":"6","stem":"资本原始积累与资本积累的区别在于（　）。","options":{"A":"前者是资本主义生产方式确立前的暴力剥夺，后者是剩余价值资本化","B":"两者完全相同","C":"前者是和平的，后者是暴力的","D":"前者发生在资本主义社会内部"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP01_7","num":"7","stem":"下列现象属于资本原始积累的是（　）。","options":{"A":"英国圈地运动","B":"资本家把利润再投资开新厂","C":"工人加班","D":"股票发行"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP01_8","num":"8","stem":"资本主义生产方式的典型特征是（　）。","options":{"A":"小手工业生产","B":"雇佣劳动和机器大生产","C":"自给自足","D":"计划生产"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP01_9","num":"9","stem":"（逻辑链·分析）资本主义经济制度形成的关键传导链是（　）。","options":{"A":"生产力发展 → 商品经济扩大 → 生产者与生产资料分离 → 一方面有人握有货币和生产资料，另一方面有人除劳动力外一无所有 → 雇佣劳动制度形成","B":"国家法律规定了资本主义制度","C":"资本家发明了机器就自动形成","D":"货币天生就是资本"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP01_10","num":"10","stem":"（逻辑链·判断）货币所有者要变成资本家，他手里的货币额必须达到一定数量。其传导原因是（　）。","options":{"A":"货币多了自然就是资本家","B":"只有货币额足够大，雇得起工人、买得起设备，带来的剩余价值才足以让所有者完全靠剥削生活 → 货币才转化为资本","C":"国家规定多少算资本家","D":"货币存银行生息就是资本"},"answer":"B"}]},{"id":"KP02","name":"货币转化为资本","file":"教材笔记/07_政治经济学/02_资本主义经济制度与生产/知识点/KP02_货币转化为资本.md","questions":[{"id":"pol_econ_02_资本主义经济制度与生产_KP02_1","num":"1","stem":"作为货币的货币与作为资本的货币的区别是（　）。","options":{"A":"前者是 W—G—W，后者是 G—W—G'","B":"前者是金属，后者是纸币","C":"前者是小面额，后者是大面额","D":"两者没有区别"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP02_2","num":"2","stem":"资本总公式是（　）。","options":{"A":"W—G—W","B":"G—W—G'","C":"G—G'","D":"W—W'"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP02_3","num":"3","stem":"资本总公式的矛盾是（　）。","options":{"A":"等价交换不能产生剩余价值，但资本流通确实带来增殖","B":"货币不能增殖","C":"商品不能交换","D":"供求不平衡"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP02_4","num":"4","stem":"解决资本总公式矛盾的条件是（　）。","options":{"A":"资本家贵卖","B":"劳动力成为商品","C":"国家补贴","D":"技术进步"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP02_5","num":"5","stem":"G' 等于（　）。","options":{"A":"G","B":"G + ΔG","C":"G - ΔG","D":"2G"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP02_6","num":"6","stem":"剩余价值（　）。","options":{"A":"在流通中产生","B":"不在流通中产生，又不能离开流通产生","C":"在生产中单独产生，与流通无关","D":"由贱买贵卖产生"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP02_7","num":"7","stem":"作为资本的货币的动机和目的是（　）。","options":{"A":"获取使用价值","B":"价值增殖","C":"满足消费","D":"收藏"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP02_8","num":"8","stem":"下列关于资本的说法，正确的是（　）。","options":{"A":"资本就是货币","B":"资本就是机器","C":"资本是能带来剩余价值的价值，体现一定社会生产关系","D":"资本是永恒范畴"},"answer":"C"},{"id":"pol_econ_02_资本主义经济制度与生产_KP02_9","num":"9","stem":"（逻辑链·分析）作为资本的货币流通公式 $G-W-G'$，其核心传导是（　）。","options":{"A":"$G' = G + \\Delta G$，这个增殖额 $\\Delta G$ 就是剩余价值，是资本运动的目的","B":"$G-W-G'$ 和简单商品流通 $W-G-W$ 没有区别","C":"剩余价值在流通中贱买贵卖产生","D":"货币本身会自行增殖"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP02_10","num":"10","stem":"（逻辑链·判断）\"资本总公式的矛盾\"是指（　）。","options":{"A":"价值增殖不能从流通中产生，但离开流通又不能实现，矛盾的解决关键是在市场上买到劳动力商品","B":"货币不能生货币","C":"商品不能交换","D":"资本家不赚钱"},"answer":"A"}]},{"id":"KP03","name":"劳动力商品","file":"教材笔记/07_政治经济学/02_资本主义经济制度与生产/知识点/KP03_劳动力商品.md","questions":[{"id":"pol_econ_02_资本主义经济制度与生产_KP03_1","num":"1","stem":"劳动力成为商品的条件是（　）。","options":{"A":"劳动者有人身自由且一无所有","B":"劳动者有土地","C":"国家规定","D":"技术进步"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP03_2","num":"2","stem":"劳动力商品的价值是由（　）决定的。","options":{"A":"劳动时间","B":"生产和再生产劳动力所必需的生活资料价值","C":"资本家决定","D":"市场供求"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP03_3","num":"3","stem":"劳动力商品使用价值的特殊性在于（　）。","options":{"A":"它能满足人的需要","B":"它是价值的源泉，且能创造大于自身价值的价值","C":"它会被消耗掉","D":"它没有使用价值"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP03_4","num":"4","stem":"劳动力价值（　）。","options":{"A":"各国相同","B":"包含历史和道德因素，各国不同","C":"永远不变","D":"由技术决定"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP03_5","num":"5","stem":"工人出卖的是（　）。","options":{"A":"劳动","B":"劳动力","C":"劳动产品","D":"生产资料"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP03_6","num":"6","stem":"某工人月工资 5000 元，他一个月劳动创造的新价值为 12000 元。剩余价值是（　）。","options":{"A":"5000 元","B":"7000 元","C":"12000 元","D":"17000 元"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP03_7","num":"7","stem":"劳动力商品与一般商品的根本区别是（　）。","options":{"A":"劳动力没有价值","B":"劳动力的使用价值能创造大于自身价值的价值","C":"劳动力不是商品","D":"劳动力没有使用价值"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP03_8","num":"8","stem":"下列关于劳动力和劳动的说法，正确的是（　）。","options":{"A":"劳动力是劳动的使用","B":"劳动是劳动力的使用，劳动力是商品，劳动不是","C":"两者等同","D":"劳动是商品，劳动力不是"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP03_9","num":"9","stem":"（逻辑链·分析）劳动力成为商品必须具备的两个条件及其推导是（　）。","options":{"A":"劳动者有人身自由（能出卖自己的劳动力）+ 劳动者一无所有（无生产资料，不得不出卖劳动力）","B":"劳动者有人身自由 + 有自己的工厂","C":"劳动者没有人身自由 + 有土地","D":"国家分配工作"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP03_10","num":"10","stem":"（逻辑链·判断）劳动力商品的使用价值区别于普通商品的根本特点是（　）。","options":{"A":"它在使用过程中能创造出比自身价值更大的价值","B":"它用完就没了","C":"它可以反复使用","D":"它的价值由供求决定"},"answer":"A"}]},{"id":"KP04","name":"劳动过程与价值增殖过程","file":"教材笔记/07_政治经济学/02_资本主义经济制度与生产/知识点/KP04_劳动过程与价值增殖过程.md","questions":[{"id":"pol_econ_02_资本主义经济制度与生产_KP04_1","num":"1","stem":"资本主义生产过程是（　）。","options":{"A":"劳动过程和价值形成过程的统一","B":"劳动过程和价值增殖过程的统一","C":"单纯的劳动过程","D":"单纯的价值增殖过程"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP04_2","num":"2","stem":"劳动过程的三个简单要素是（　）。","options":{"A":"劳动、劳动对象、劳动资料","B":"生产、分配、消费","C":"c、v、m","D":"生产力、生产关系、上层建筑"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP04_3","num":"3","stem":"价值增殖过程是（　）。","options":{"A":"超过劳动力价值补偿点而延长了的价值形成过程","B":"单纯的价值形成过程","C":"生产使用价值的过程","D":"商品交换过程"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP04_4","num":"4","stem":"工人工作日 8 小时，前 4 小时创造的价值等于工资。后 4 小时创造的价值是（　）。","options":{"A":"劳动力价值","B":"剩余价值","C":"生产资料价值","D":"新创造价值 = 0"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP04_5","num":"5","stem":"资本主义劳动过程的特点是（　）。","options":{"A":"工人在资本家监督下劳动，产品归资本家所有","B":"工人自由劳动，产品归自己","C":"劳动过程与社会无关","D":"没有监督"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP04_6","num":"6","stem":"在生产过程中，具体劳动（　）。","options":{"A":"转移生产资料价值","B":"创造新价值","C":"创造剩余价值","D":"什么也不做"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP04_7","num":"7","stem":"在生产过程中，抽象劳动（　）。","options":{"A":"转移生产资料价值","B":"创造新价值（v+m）","C":"创造使用价值","D":"转移劳动力价值"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP04_8","num":"8","stem":"价值形成过程与价值增殖过程的区别在于（　）。","options":{"A":"前者新价值 = v，后者新价值 = v + m","B":"前者是商品生产，后者不是","C":"前者有劳动，后者没有","D":"两者没有区别"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP04_9","num":"9","stem":"（逻辑链·分析）价值形成过程转变为价值增殖过程的传导是（　）。","options":{"A":"价值形成过程 = 补偿劳动力价值的劳动时间；延长到补偿劳动力价值所需时间以上 → 剩余价值被创造出来 → 价值形成过程变为价值增殖过程","B":"生产一开始就是增殖过程","C":"增殖在流通中产生","D":"机器自动增殖"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP04_10","num":"10","stem":"（逻辑链·判断）某奶茶店工人每天劳动 8 小时，其中 4 小时就补偿了老板支付的工资。则剩余价值率为（　）。","options":{"A":"50%","B":"100%","C":"200%","D":"25%"},"answer":"B"}]},{"id":"KP05","name":"不变资本与可变资本","file":"教材笔记/07_政治经济学/02_资本主义经济制度与生产/知识点/KP05_不变资本与可变资本.md","questions":[{"id":"pol_econ_02_资本主义经济制度与生产_KP05_1","num":"1","stem":"划分不变资本和可变资本的依据是（　）。","options":{"A":"资本不同部分在剩余价值生产中的作用","B":"资本周转方式","C":"资本的实物形态","D":"资本的来源"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP05_2","num":"2","stem":"不变资本是（　）。","options":{"A":"以生产资料形式存在的资本","B":"以劳动力形式存在的资本","C":"固定资本","D":"流动资本"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP05_3","num":"3","stem":"可变资本是（　）。","options":{"A":"以生产资料形式存在的资本","B":"以劳动力形式存在的资本，在生产中增殖","C":"货币资本","D":"商品资本"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP05_4","num":"4","stem":"商品价值构成公式是（　）。","options":{"A":"W = c + v","B":"W = c + v + m","C":"W = v + m","D":"W = c + m"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP05_5","num":"5","stem":"下列属于不变资本的是（　）。","options":{"A":"工人工资","B":"原料、机器、厂房","C":"原材料和工资","D":"利润"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP05_6","num":"6","stem":"区分 c 和 v 的意义在于（　）。","options":{"A":"揭示剩余价值的真正来源","B":"计算周转速度","C":"划分固定资产","D":"计算成本"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP05_7","num":"7","stem":"某资本家预付 c = 8000 元，v = 2000 元，m = 2000 元。W 为（　）。","options":{"A":"10000 元","B":"12000 元","C":"8000 元","D":"4000 元"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP05_8","num":"8","stem":"下列关于 c 和 v 的说法，错误的是（　）。","options":{"A":"c 是生产资料，v 是劳动力","B":"c 转移价值，v 创造新价值","C":"c 一定是固定资本，v 一定是流动资本","D":"划分依据是在剩余价值生产中的作用"},"answer":"C"},{"id":"pol_econ_02_资本主义经济制度与生产_KP05_9","num":"9","stem":"（逻辑链·分析）把资本划分为不变资本 $c$ 和可变资本 $v$ 的依据和意义是（　）。","options":{"A":"按在剩余价值生产中的作用划分：生产资料是不变资本 $c$（只转移旧价值不增殖），劳动力是可变资本 $v$（能创造比自身更大价值）","B":"按资本周转快慢划分","C":"按资本形态划分","D":"按设备和现金划分"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP05_10","num":"10","stem":"（逻辑链·判断）某资本家投 10 万，其中 7 万买设备原料、3 万雇工人，一个月榨取剩余价值 3 万。下列正确的是（　）。","options":{"A":"不变资本 $c = 7$ 万，可变资本 $v = 3$ 万，剩余价值率 $m' = 3/3 = 100\\%$","B":"$c = 3$ 万，$v = 7$ 万","C":"剩余价值率 $= 3/10 = 30\\%$","D":"设备也创造了剩余价值"},"answer":"A"}]},{"id":"KP06","name":"剩余价值率","file":"教材笔记/07_政治经济学/02_资本主义经济制度与生产/知识点/KP06_剩余价值率.md","questions":[{"id":"pol_econ_02_资本主义经济制度与生产_KP06_1","num":"1","stem":"剩余价值率是（　）。","options":{"A":"m/v","B":"m/(c+v)","C":"v/m","D":"c/(c+v)"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP06_2","num":"2","stem":"剩余价值率也可以表示为（　）。","options":{"A":"剩余劳动时间/必要劳动时间","B":"必要劳动时间/剩余劳动时间","C":"不变资本/可变资本","D":"利润/成本"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP06_3","num":"3","stem":"某资本家 v = 2000 元，m = 2000 元。m' 为（　）。","options":{"A":"50%","B":"100%","C":"200%","D":"150%"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP06_4","num":"4","stem":"工作日 12 小时，必要劳动时间 6 小时。m' 为（　）。","options":{"A":"50%","B":"100%","C":"200%","D":"150%"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP06_5","num":"5","stem":"剩余价值率与利润率的关系是（　）。","options":{"A":"m' > p'","B":"m' < p'","C":"m' = p'","D":"无关"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP06_6","num":"6","stem":"某资本家 c = 8000，v = 2000，m = 2000。利润率 p' 为（　）。","options":{"A":"20%","B":"25%","C":"100%","D":"50%"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP06_7","num":"7","stem":"m' 反映的是（　）。","options":{"A":"资本家的赚钱程度","B":"资本家对工人的剥削程度","C":"资本周转速度","D":"技术水平"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP06_8","num":"8","stem":"提高剩余价值率的方法有（　）。","options":{"A":"绝对剩余价值生产和相对剩余价值生产","B":"延长工作日和提高劳动生产率","C":"A 和 B","D":"增加工人工资"},"answer":"C"},{"id":"pol_econ_02_资本主义经济制度与生产_KP06_9","num":"9","stem":"（逻辑链·分析）剩余价值率 $m' = m/v$ 还可以表示为（　）。","options":{"A":"$m' = $ 剩余劳动时间 / 必要劳动时间 = 剩余劳动 / 必要劳动","B":"$m' = m/(c+v)$","C":"$m' = v/m$","D":"$m' = c/(c+v)$"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP06_10","num":"10","stem":"（逻辑链·判断）奶茶店老板投 5 万设备（$c$）、雇 1 人月工资 5000 元（$v$）、月榨取剩余价值 5000 元（$m$）。剩余价值率和利润率分别是（　）。","options":{"A":"$m' = 100\\%$，$p' \\approx 9.1\\%$","B":"$m' = 9.1\\%$，$p' = 100\\%$","C":"$m' = 50\\%$，$p' = 50\\%$","D":"$m' = 10\\%$，$p' = 10\\%$"},"answer":"A"}]},{"id":"KP07","name":"绝对剩余价值与相对剩余价值","file":"教材笔记/07_政治经济学/02_资本主义经济制度与生产/知识点/KP07_绝对剩余价值与相对剩余价值.md","questions":[{"id":"pol_econ_02_资本主义经济制度与生产_KP07_1","num":"1","stem":"绝对剩余价值是（　）。","options":{"A":"必要劳动时间不变，延长工作日长度生产的 m","B":"工作日长度不变，缩短必要劳动时间生产的 m","C":"个别企业提高生产率获得的 m","D":"提高劳动强度获得的 m"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP07_2","num":"2","stem":"相对剩余价值是（　）。","options":{"A":"延长工作日生产的 m","B":"工作日不变，缩短必要劳动时间生产的 m","C":"个别企业多得的 m","D":"提高劳动强度生产的 m"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP07_3","num":"3","stem":"工作日 8 小时，必要劳动 4 小时。现延长到 10 小时，必要劳动不变。新 m' 为（　）。","options":{"A":"100%","B":"150%","C":"200%","D":"50%"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP07_4","num":"4","stem":"工作日 8 小时，必要劳动 4 小时。现工作日延长到 12 小时，必要劳动不变。新 m' 为（　）。","options":{"A":"100%","B":"150%","C":"200%","D":"50%"},"answer":"C"},{"id":"pol_econ_02_资本主义经济制度与生产_KP07_5","num":"5","stem":"超额剩余价值是（　）。","options":{"A":"个别资本家提高生产率，个别价值低于社会价值多得的 m","B":"全社会生产率提高带来的 m","C":"延长工作日带来的 m","D":"延长劳动强度带来的 m"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP07_6","num":"6","stem":"相对剩余价值是通过（　）实现的。","options":{"A":"个别资本家提高生产率","B":"全社会劳动生产率普遍提高，降低劳动力价值","C":"延长工作日","D":"降低工资"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP07_7","num":"7","stem":"绝对剩余价值和相对剩余价值的关系是（　）。","options":{"A":"前者是资本主义体系的一般基础，后者是机器大工业后的主要方法","B":"两者完全无关","C":"后者是前者的基础","D":"前者比后者更高级"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP07_8","num":"8","stem":"下列属于相对剩余价值生产的是（　）。","options":{"A":"加班","B":"流水线、泰勒制、算法监控提高劳动强度","C":"996","D":"周末上班"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP07_9","num":"9","stem":"（逻辑链·分析）绝对剩余价值生产和相对剩余价值生产的区别传导是（　）。","options":{"A":"绝对剩余价值 = 在必要劳动时间不变下延长工作日长度；相对剩余价值 = 在工作日长度不变下提高社会劳动生产率、缩短必要劳动时间","B":"二者完全一样","C":"绝对剩余价值靠技术进步","D":"相对剩余价值靠加班"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP07_10","num":"10","stem":"（逻辑链·判断）全社会劳动生产率普遍提高后，在工作日长度不变的情况下，剩余价值率会（　）。","options":{"A":"提高（必要劳动时间缩短，相对剩余价值增加）","B":"下降","C":"不变","D":"先升后降"},"answer":"A"}]},{"id":"KP08","name":"资本主义工资","file":"教材笔记/07_政治经济学/02_资本主义经济制度与生产/知识点/KP08_资本主义工资.md","questions":[{"id":"pol_econ_02_资本主义经济制度与生产_KP08_1","num":"1","stem":"资本主义工资的本质是（　）。","options":{"A":"劳动的价格","B":"劳动力的价值或价格","C":"劳动的报酬","D":"工人全部劳动的报酬"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP08_2","num":"2","stem":"工资的两种基本形式是（　）。","options":{"A":"计时工资和计件工资","B":"货币工资和实物工资","C":"名义工资和实际工资","D":"奖金和津贴"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP08_3","num":"3","stem":"计件工资（　）。","options":{"A":"是计时工资的转化形式，更隐蔽","B":"比计时工资更公平","C":"是工资的唯一形式","D":"与剩余价值无关"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP08_4","num":"4","stem":"名义工资与实际工资的关系是（　）。","options":{"A":"名义工资上涨，实际工资一定上涨","B":"实际工资 = 名义工资能买到的生活资料数量","C":"两者无关","D":"实际工资永远高于名义工资"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP08_5","num":"5","stem":"工资形式掩盖剥削是因为（　）。","options":{"A":"工资看起来是全部劳动的报酬，实际上只补偿必要劳动","B":"工资太高","C":"工资由国家规定","D":"工资与劳动无关"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP08_6","num":"6","stem":"工人出卖的是（　）。","options":{"A":"劳动","B":"劳动力","C":"劳动产品","D":"生产资料"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP08_7","num":"7","stem":"发达国家工资高的根本原因是（　）。","options":{"A":"资本家仁慈","B":"那里劳动生产率高、劳动力价值高（教育、生活成本高）","C":"国家规定","D":"工人更懒"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP08_8","num":"8","stem":"下列关于工资的说法，错误的是（　）。","options":{"A":"工资是劳动力价值或价格","B":"工资表现为劳动的价格是假象","C":"工资是全部劳动的报酬","D":"计件工资比计时工资更隐蔽"},"answer":"C"},{"id":"pol_econ_02_资本主义经济制度与生产_KP08_9","num":"9","stem":"（逻辑链·分析）资本主义工资本质上是（　）。","options":{"A":"劳动力价值或价格的转化形式，但表现为劳动的价格，掩盖了必要劳动和剩余劳动的区别","B":"劳动的报酬，等于全部劳动创造的价值","C":"工人全部劳动的等价物","D":"由供求决定的工资"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP08_10","num":"10","stem":"（逻辑链·判断）说\"工资是劳动的价格\"为什么是错误的？最准确的传导是（　）。","options":{"A":"劳动不是商品（它在出卖前不存在，无法买卖）；工人出卖的是劳动力，工资只是劳动力价值的转化形式","B":"工资太低","C":"工资太高","D":"工资由工会决定"},"answer":"A"}]},{"id":"KP09","name":"资本积累","file":"教材笔记/07_政治经济学/02_资本主义经济制度与生产/知识点/KP09_资本积累.md","questions":[{"id":"pol_econ_02_资本主义经济制度与生产_KP09_1","num":"1","stem":"资本积累是（　）。","options":{"A":"剩余价值的资本化","B":"资本家节欲","C":"货币储蓄","D":"国家投资"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP09_2","num":"2","stem":"资本主义再生产的特征是（　）。","options":{"A":"简单再生产","B":"扩大再生产","C":"有时简单有时扩大","D":"缩小再生产"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP09_3","num":"3","stem":"资本积累的内在动力是（　）。","options":{"A":"资本家节欲","B":"追求剩余价值的无限贪欲","C":"国家要求","D":"工人监督"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP09_4","num":"4","stem":"资本积累的外在压力是（　）。","options":{"A":"竞争","B":"道德","C":"法律","D":"传统"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP09_5","num":"5","stem":"影响资本积累量的因素不包括（　）。","options":{"A":"剩余价值率","B":"社会劳动生产率水平","C":"预付资本量","D":"资本家的个人消费偏好"},"answer":"D"},{"id":"pol_econ_02_资本主义经济制度与生产_KP09_6","num":"6","stem":"简单再生产是指（　）。","options":{"A":"剩余价值全部用于个人消费，生产在原有规模重复","B":"剩余价值一部分再投资","C":"生产规模扩大","D":"生产规模缩小"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP09_7","num":"7","stem":"资本积累的源泉是（　）。","options":{"A":"资本家节欲","B":"剩余价值","C":"国家补贴","D":"国际贸易"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP09_8","num":"8","stem":"马克思批判\"节欲论\"，认为资本积累是（　）。","options":{"A":"资本家道德选择","B":"资本主义生产方式的客观规律，由竞争和贪欲决定","C":"偶然现象","D":"国家政策"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP09_9","num":"9","stem":"（逻辑链·分析）资本积累的传导链是（　）。","options":{"A":"资本家把剩余价值的一部分不用于个人消费，而是资本化（追加投资）→ 扩大生产规模 → 榨取更多剩余价值 → 资本积累不断扩大","B":"资本家省吃俭用攒出资本","C":"资本积累就是存钱","D":"资本积累靠国家拨款"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP09_10","num":"10","stem":"（逻辑链·判断）资本积累必然导致相对过剩人口（失业大军），其传导是（　）。","options":{"A":"资本积累 → 资本有机构成 $c:v$ 提高（机器越来越多）→ 对劳动力的相对需求减少 → 一部分工人被机器排挤 → 相对过剩人口","B":"人口自然增长太快","C":"工人太懒","D":"经济周期波动"},"answer":"A"}]},{"id":"KP10","name":"资本有机构成","file":"教材笔记/07_政治经济学/02_资本主义经济制度与生产/知识点/KP10_资本有机构成.md","questions":[{"id":"pol_econ_02_资本主义经济制度与生产_KP10_1","num":"1","stem":"资本有机构成是指（　）。","options":{"A":"由技术构成决定并反映技术构成变化的价值构成（c:v）","B":"生产资料数量与劳动力数量的比例","C":"c + v","D":"固定资本与流动资本的比例"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP10_2","num":"2","stem":"随着资本积累和技术进步，资本有机构成（　）。","options":{"A":"不断提高","B":"不断下降","C":"不变","D":"时而提高时而下降"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP10_3","num":"3","stem":"资本有机构成提高意味着（　）。","options":{"A":"c 比重增大，v 比重减小","B":"v 比重增大，c 比重减小","C":"c 和 v 同比例增大","D":"c 和 v 同比例减小"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP10_4","num":"4","stem":"相对过剩人口是指（　）。","options":{"A":"人口绝对过剩","B":"劳动力供给超过资本对它的需求","C":"社会养不起的人口","D":"老年人"},"answer":"B"},{"id":"pol_econ_02_资本主义经济制度与生产_KP10_5","num":"5","stem":"资本有机构成提高会导致（　）。","options":{"A":"利润率下降趋势","B":"相对过剩人口形成","C":"资本积聚和集中","D":"以上都对"},"answer":"D"},{"id":"pol_econ_02_资本主义经济制度与生产_KP10_6","num":"6","stem":"某企业 c = 6 万，v = 4 万，m' = 100%。p' 为（　）。","options":{"A":"40%","B":"60%","C":"100%","D":"25%"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP10_7","num":"7","stem":"资本积聚与资本集中的区别是（　）。","options":{"A":"积聚是单个资本通过积累增大；集中是分散资本合并","B":"两者相同","C":"积聚是并购","D":"集中是剩余价值资本化"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP10_8","num":"8","stem":"下列关于相对过剩人口的说法，错误的是（　）。","options":{"A":"它是资本积累的必然产物","B":"它是资本主义生产方式存在的条件（产业后备军）","C":"它是人口绝对过剩","D":"它压低在职工人工资"},"answer":"C"},{"id":"pol_econ_02_资本主义经济制度与生产_KP10_9","num":"9","stem":"（逻辑链·分析）资本有机构成 $c:v$ 提高对利润率 $p'$ 的影响传导是（　）。","options":{"A":"剩余价值率 $m'$ 不变下，$c:v$ 提高 → 可变资本 $v$ 在总资本中占比下降 → $p' = m/(c+v) = m'/(c/v+1)$ 下降","B":"$c:v$ 提高利润率上升","C":"有机构成与利润率无关","D":"利润率只由 $c$ 决定"},"answer":"A"},{"id":"pol_econ_02_资本主义经济制度与生产_KP10_10","num":"10","stem":"（逻辑链·判断）两个部门同样的剥削率 $m' = 100\\%$，A 部门 $c:v = 9:1$，B 部门 $c:v = 1:1$。则（　）。","options":{"A":"A 部门利润率低于 B 部门（因为有机构成高）","B":"A 部门利润率高于 B 部门","C":"两部门利润率相同","D":"无法比较"},"answer":"A"}]}]};
